verifyCmd:
node <<'VERIFYJS'
const g = require('./jsonPointer.js');
const doc = { foo: ['bar', 'baz'], '': 0, 'a/b': 1, 'm~n': 2, ' ': 3, nested: { x: { y: 'deep' } }, nul: null, und: undefined };
const t = (ptr, want, m) => { const got = g(doc, ptr); if (got !== want) { console.error('FAIL', m, ptr, JSON.stringify(got)); process.exit(1); } };
if (g(doc, '') !== doc) { console.error('empty pointer is whole doc'); process.exit(1); }
t('/foo/0', 'bar', 'array index');
t('/foo/1', 'baz', 'array index 1');
t('/', 0, 'empty key');
t('/a~1b', 1, '~1 unescapes to slash');
t('/m~0n', 2, '~0 unescapes to tilde');
t('/ ', 3, 'space key');
t('/nested/x/y', 'deep', 'nested');
t('/nope', undefined, 'missing key');
t('/foo/5', undefined, 'index out of range');
t('/foo/01', undefined, 'leading zero is not an index');
t('/foo/x', undefined, 'non-numeric array token');
t('/nul', null, 'null value returned as null');
t('/und', undefined, 'present-undefined');
t('/nul/deeper', undefined, 'descend through null');
if (g({ '~1': 9 }, '/~01') !== 9) { console.error('~0 then ~1 ordering'); process.exit(1); }
try { g(doc, 'foo'); console.error('no throw on missing leading slash'); process.exit(1); } catch (e) {}
console.log('ok');
VERIFYJS
